select t.machine_id,t.machine_id machineId,t.model_id,t.model_id modelId,t.mmm_id,t.mmm_id
mmmId,t.community_id,t.community_id communityId,mma.machine_name machineName,
mma.machine_code machineCode,mma.location_name locationName,ma.ma_name maName,
mm.model_name modelName
from monitor_machine_model t
left join monitor_model mm on t.model_id = mm.model_id
left join monitor_machine mma on t.machine_id = mma.machine_id
left join monitor_area ma on mma.ma_id = ma.ma_id
where 1 =1 and mm.status_cd = '0' and mma.status_cd = '0' and ma.status_cd = '0'

    and t.machine_id= #{machineId}


    and t.model_id= #{modelId}


    and t.mmm_id= #{mmmId}


    and t.community_id= #{communityId}


    and t.status_cd= #{statusCd}


    and mma.machine_name like concat('%', #{machineName}, '%')


    and mma.location_name like concat('%', #{locationName}, '%')


    and ma.ma_id= #{maId}

order by t.create_time desc

    limit #{page}, #{row}

